const mb = new Intl.NumberFormat("it-IT", { maximumFractionDigits: 1 });
/** 73535380 -> "70,1 MB" (binary megabytes, as Windows Explorer shows them). */
export function fmtBytes(n: number): string {
  if (n < 1024 * 1024) return `${Math.max(1, Math.round(n / 1024))} KB`;
  return `${mb.format(n / (1024 * 1024))} MB`;
}

/** "2026-11-03" -> "3 novembre 2026" */
export function fmtDate(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  return new Intl.DateTimeFormat("it-IT", { day: "numeric", month: "long", year: "numeric" }).format(
    new Date(y, m - 1, d),
  );
}

/** "Versione 1.0.0 · Windows 10 e 11" */
export const downloadReadyMeta = (v: string | null) => (v ? `Versione ${v} · Windows 10 e 11` : "Windows 10 e 11");
